[metadata] {"type": "create", "filePath": "/workspace/repo/packages/insomnia/src/common/spectral-ruleset-validator.ts", "content": "import { parse } from 'yaml';

/**
 * Validation for custom Spectral rulesets.
 *
 * Insomnia allows users to supply their own Spectral ruleset for OpenAPI
 * linting. Because a ruleset can reference remote content and describe rule
 * behaviour, we validate it against a conservative allow-list before ever
 * handing it to Spectral. This guards against prototype pollution, arbitrary
 * code execution via custom `functions`, and unexpected top-level keys.
 */

type ValidationResult = { isValid: true } | { isValid: false; error: string };

/** Top-level keys we permit in a ruleset. Notably `functions` is excluded. */
const ALLOWED_TOP_LEVEL_KEYS = new Set([
  'extends',
  'rules',
  'documentationUrl',
  'aliases',
  'overrides',
  'formats',
  'parserOptions',
]);

/** Spectral's built-in rule functions. Custom functions are not permitted. */
const BUILTIN_FUNCTIONS = new Set([
  'alphabetical',
  'casing',
  'defined',
  'enumeration',
  'falsy',
  'length',
  'pattern',
  'schema',
  'truthy',
  'typedEnum',
  'undefined',
  'unreferencedReusableObject',
  'or',
  'xor',
]);

/** Valid severity shorthand strings for a rule body. */
const SEVERITY_STRINGS = new Set(['error', 'warn', 'info', 'hint', 'off']);

/** Tokens that could be used for prototype pollution. */
const PROTO_TOKENS = ['__proto__', 'constructor', 'prototype'];

/**
 * Normalise a value to an array: `undefined` becomes `[]`, a single value is
 * wrapped in a one-element array and an existing array is returned unchanged.
 */
export function toArray<T>(value: T | T[] | undefined): T[] {
  if (value === undefined) {
    return [];
  }
  return Array.isArray(value) ? value : [value];
}

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/**
 * Validate a (rule-level or top-level) `documentationUrl`. Non-string values
 * are ignored. Returns an error message if the URL is not a valid https URL.
 */
const validateDocumentationUrl = (value: unknown): string | null => {
  if (typeof value !== 'string') {
    return null;
  }
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:') {
      return 'documentationUrl must use the https scheme.';
    }
  } catch {
    return 'documentationUrl is not a valid https URL.';
  }
  return null;
};

const validateThenEntry = (ruleName: string, thenEntry: Record<string, unknown>): string | null => {
  if ('field' in thenEntry) {
    const field = thenEntry.field;
    if (typeof field === 'string') {
      const hasProtoToken = PROTO_TOKENS.some(token => field.includes(token));
      const hasTraversal = field.includes('.') || field.includes('[') || field.includes(']');
      if (hasProtoToken || hasTraversal) {
        return `Rule "${ruleName}" has a "then.field" containing a disallowed value.`;
      }
    }
  }
  if ('function' in thenEntry) {
    const fn = thenEntry.function;
    if (typeof fn !== 'string' || !BUILTIN_FUNCTIONS.has(fn)) {
      return `Rule "${ruleName}" uses "${String(fn)}" which is not an allowed function.`;
    }
  }
  return null;
};

const validateRuleBody = (ruleName: string, ruleBody: unknown): string | null => {
  if (typeof ruleBody === 'boolean') {
    return null;
  }
  if (typeof ruleBody === 'string') {
    if (SEVERITY_STRINGS.has(ruleBody)) {
      return null;
    }
    return `Rule "${ruleName}" must be an object, boolean, or severity string.`;
  }
  if (!isPlainObject(ruleBody)) {
    return `Rule "${ruleName}" must be an object, boolean, or severity string.`;
  }

  // `given` may be a single expression or an array of expressions.
  if ('given' in ruleBody) {
    for (const given of toArray(ruleBody.given)) {
      if (typeof given !== 'string') {
        continue;
      }
      if (PROTO_TOKENS.some(token => given.includes(token))) {
        return `Rule "${ruleName}" has a "given" expression containing a disallowed token.`;
      }
    }
  }

  const docUrlError = validateDocumentationUrl(ruleBody.documentationUrl);
  if (docUrlError) {
    return docUrlError;
  }

  // `then` may be a single object or an array of objects.
  if ('then' in ruleBody) {
    for (const thenEntry of toArray(ruleBody.then)) {
      if (!isPlainObject(thenEntry)) {
        continue;
      }
      const thenError = validateThenEntry(ruleName, thenEntry);
      if (thenError) {
        return thenError;
      }
    }
  }

  return null;
};

/**
 * Validate the textual content of a Spectral ruleset (YAML or JSON).
 */
export function validateSpectralRuleset(content: string): ValidationResult {
  if (!content || !content.trim()) {
    return { isValid: false, error: 'Ruleset is empty.' };
  }

  let parsed: unknown;
  try {
    parsed = parse(content);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return { isValid: false, error: `Ruleset could not be parsed as YAML or JSON: ${message}` };
  }

  if (!isPlainObject(parsed)) {
    return { isValid: false, error: 'Ruleset must be an object.' };
  }

  const keys = Object.keys(parsed);
  if (keys.length === 0) {
    return { isValid: false, error: 'Ruleset must declare at least one of "extends" or "rules".' };
  }

  for (const key of keys) {
    if (!ALLOWED_TOP_LEVEL_KEYS.has(key)) {
      return { isValid: false, error: `Unsupported top-level key "${key}" in ruleset.` };
    }
  }

  if ('extends' in parsed) {
    for (const entry of toArray(parsed.extends)) {
      if (typeof entry !== 'string') {
        return { isValid: false, error: 'All "extends" entries must be strings.' };
      }
    }
  }

  const topDocUrlError = validateDocumentationUrl(parsed.documentationUrl);
  if (topDocUrlError) {
    return { isValid: false, error: topDocUrlError };
  }

  if ('rules' in parsed) {
    const rules = parsed.rules;
    if (!isPlainObject(rules)) {
      return { isValid: false, error: '"rules" must be an object.' };
    }
    for (const [ruleName, ruleBody] of Object.entries(rules)) {
      if (isPlainObject(ruleBody) && PROTO_TOKENS.includes(ruleName)) {
        return { isValid: false, error: `Rule name "${ruleName}" is not allowed.` };
      }
      const ruleError = validateRuleBody(ruleName, ruleBody);
      if (ruleError) {
        return { isValid: false, error: ruleError };
      }
    }
  }

  return { isValid: true };
}
