/**
 * Bundles a custom Spectral ruleset into a single self-contained YAML document.
 *
 * - Local file `extends` are read recursively and their rules are flattened
 *   into the parent ruleset. On a name collision the parent's rule wins.
 * - Built-in spectral identifiers (`spectral:oas`, ...) are preserved in the
 *   output `extends` and de-duplicated.
 * - Remote https `extends` are validated (fetched + checked) for safety but
 *   their content is NOT merged; the URL is preserved in the output `extends`.
 *
 * The recursion is bounded to guard against runaway or malicious rulesets and
 * remote fetches are subject to SSRF protections (https-only, no private or
 * loopback hosts, DNS re-resolution before fetch).
 */

const MAX_EXTENDS_DEPTH = 5;
const MAX_REMOTE_DEPTH = 5;

const SPECTRAL_BUILTIN_IDENTIFIERS = new Set([
  'spectral:oas',
  'spectral:asyncapi',
  'spectral:arazzo',
]);

type ExtendsKind = 'builtin' | 'remote' | 'file' | 'invalid';

interface BundleResult {
  rules: Record<string, unknown>;
  builtins: Set<string>;
  remotes: string[];
}

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const stripBrackets = (host: string): string =>
  host.startsWith('[') && host.endsWith(']') ? host.slice(1, -1) : host;

const isIpLiteral = (host: string): boolean => {
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) {
    return true;
  }
  return host.includes(':');
};

const isYamlFile = (target: string): boolean =>
  /\.ya?ml$/i.test(target);

const isFilePath = (entry: string): boolean =>
  entry.startsWith('./') ||
  entry.startsWith('../') ||
  entry.startsWith('/') ||
  entry.startsWith('.\\') ||
  entry.startsWith('..\\') ||
  /^[a-zA-Z]:[\\/]/.test(entry);

const classifyExtends = (entry: string): ExtendsKind => {
  if (SPECTRAL_BUILTIN_IDENTIFIERS.has(entry)) {
    return 'builtin';
  }
  let url: URL | null = null;
  try {
    url = new URL(entry);
  } catch {
    url = null;
  }
  if (url && url.hostname && ['https:', 'http:', 'ftp:'].includes(url.protocol)) {
    return 'remote';
  }
  if (isFilePath(entry)) {
    return 'file';
  }
  return 'invalid';
};

const readRulesetFile = async (filePath: string): Promise<Record<string, unknown>> => {
  const raw = await fs.promises.readFile(filePath, 'utf-8');
